<template><main class="page-width page-shell"><div class="page-title"><span class="eyebrow">YOUR BASKET</span><h1>Shopping cart</h1><p>{{ store.cartCount }} items ready for checkout</p></div><div v-if="store.cartItems.length" class="cart-layout"><section class="cart-items"><article v-for="item in store.cartItems" :key="item.id" class="cart-row"><img :src="item.image" :alt="item.name"><div class="item-copy"><h3>{{ item.name }}</h3><small>{{ store.getCategoryById(item.category)?.name || 'Market favourite' }}</small><b>${{ item.price.toFixed(2) }}</b></div><div class="qty"><button @click="store.decreamentQ(item)">−</button><span>{{ item.quantity }}</span><button @click="store.increamentQ(item)">+</button></div><strong class="line-total">${{ (item.price * item.quantity).toFixed(2) }}</strong><button class="remove" @click="store.removeFromCart(item)" aria-label="Remove item"><Icon icon="mdi:trash-can-outline"/></button></article><router-link to="/shop" class="continue">← Continue shopping</router-link></section><aside class="summary"><h2>Order summary</h2><div><span>Subtotal</span><b>${{ store.cartTotal.toFixed(2) }}</b></div><div><span>Delivery</span><b>{{ store.cartTotal >= 50 ? 'FREE' : '$4.99' }}</b></div><div class="total"><span>Total</span><b>${{ (store.cartTotal + (store.cartTotal >= 50 ? 0 : 4.99)).toFixed(2) }}</b></div><router-link to="/checkout" class="checkout-btn">Continue to checkout <Icon icon="mdi:arrow-right"/></router-link><p><Icon icon="mdi:shield-check-outline"/> Secure checkout · No hidden fees</p></aside></div><div v-else class="empty-cart"><div><Icon icon="mdi:shopping-outline" width="48"/></div><h2>Your basket is taking a break</h2><p>Looks like you haven't added anything just yet.</p><router-link to="/shop" class="checkout-btn">Find something lovely</router-link></div></main></template>
